-- Decks for the gifts, photography and dance groups (destination 'wedding'). Gifts has nothing between the two of you
-- (decided: no wedding gift between the couple). Outfit-style cards elsewhere link to image searches; these cards do too.
insert into swipe_decks (key, label, description, sort_order, destination) values ($q$wedding-gifts$q$, $q$Gifts: family and guests$q$, $q$Gift ideas for family, guests and helpers. You two agreed there is no gift between you, so this is only for other people.$q$, 100, 'wedding');
insert into swipe_decks (key, label, description, sort_order, destination) values ($q$wedding-photography$q$, $q$Photography and video$q$, $q$What kind of photos and film you want, and which shots matter. Budget context from the chat: about 1.5 lakh hoped for, and one quote of 2 to 2.1 lakh all-inclusive.$q$, 110, 'wedding');
insert into swipe_decks (key, label, description, sort_order, destination) values ($q$wedding-dance$q$, $q$Sangeet: dance and performances$q$, $q$The Sangeet dance plan. You decided to start with small pieces and build up, and to practise about 30 minutes in the evening.$q$, 120, 'wedding');
insert into swipe_cards (deck_id, title, subtitle, detail, emoji, category, facts, links, sort_order)
