from swipe_decks d, (values
($q$Candid, natural photos$q$, $q$Photo style$q$, $q$Unposed moments: laughs, reactions, family emotions. The photographer stays in the background. The modern favourite, but you still need a few posed family groups.$q$, $q$📷$q$, $q$Style$q$, $q$candid wedding photography india natural moments$q$, $q$[{"label": "Feel", "value": "Natural"}]$q$, 1),
($q$Traditional posed portraits$q$, $q$Photo style$q$, $q$Planned group and couple portraits, the classic way. Safe for family albums and elders, but it can feel stiff and takes time.$q$, $q$🖼️$q$, $q$Style$q$, $q$traditional posed wedding portraits india family$q$, $q$[{"label": "Feel", "value": "Formal"}]$q$, 2),
($q$A mix of candid and posed$q$, $q$Photo style$q$, $q$Candid through the day, with a short list of posed family and couple shots at set times. Most couples choose this.$q$, $q$🎯$q$, $q$Style$q$, $q$wedding photography candid and traditional mix$q$, $q$[{"label": "Feel", "value": "Balanced"}]$q$, 3),
($q$Bright and airy colours$q$, $q$Look$q$, $q$Light, clean, soft colours. Fresh and modern, and it flatters pastel outfits and decor.$q$, $q$☀️$q$, $q$Look$q$, $q$bright airy wedding photography india$q$, $q$[{"label": "Mood", "value": "Light and fresh"}]$q$, 4),
($q$Warm and rich colours$q$, $q$Look$q$, $q$Deeper, golden tones with rich colour. Suits red, gold and marigold, and festive nights.$q$, $q$🌅$q$, $q$Look$q$, $q$warm rich colour wedding photography india gold$q$, $q$[{"label": "Mood", "value": "Warm and festive"}]$q$, 5),
($q$Moody and cinematic$q$, $q$Look$q$, $q$Darker, higher contrast, film-like. Dramatic and stylish, but it can look heavy on bright haldi and mehndi days.$q$, $q$🎞️$q$, $q$Look$q$, $q$cinematic moody wedding photography india$q$, $q$[{"label": "Mood", "value": "Dramatic"}]$q$, 6),
($q$Cinematic wedding film$q$, $q$Video$q$, $q$A 5 to 10 minute highlight film with music, edited like a short movie. The thing most couples rewatch.$q$, $q$🎬$q$, $q$Video$q$, $q$cinematic wedding highlight film india$q$, $q$[{"label": "Deliverable", "value": "5 to 10 minute film"}]$q$, 7),
($q$Full-length ceremony video$q$, $q$Video$q$, $q$The whole ceremony recorded in one go, including the pheras. Long, but it is the only record of the whole night.$q$, $q$📹$q$, $q$Video$q$, $q$full length wedding ceremony video india$q$, $q$[{"label": "Deliverable", "value": "Full ceremony"}]$q$, 8),
($q$Short teaser or reel$q$, $q$Video$q$, $q$A 30 to 60 second teaser or reel for sharing quickly, often within a week or two.$q$, $q$📱$q$, $q$Video$q$, $q$wedding teaser reel instagram india$q$, $q$[{"label": "Deliverable", "value": "30 to 60 seconds"}]$q$, 9),
($q$Drone shots$q$, $q$Add-on$q$, $q$Aerial shots of the venue and the baraat. Check the venue allows drones and whether it is safe with crowds.$q$, $q$🚁$q$, $q$Add-on$q$, $q$wedding drone shots india baraat$q$, $q$[{"label": "Check", "value": "Venue permission"}]$q$, 10),
($q$Same-day edit or quick preview$q$, $q$Add-on$q$, $q$A few edited photos sent the same night or next morning. Fun to share, and some teams charge extra.$q$, $q$⚡$q$, $q$Add-on$q$, $q$same day edit wedding photos preview$q$, $q$[{"label": "Extra cost", "value": "Often"}]$q$, 11),
($q$Pre-wedding shoot$q$, $q$Extra shoot$q$, $q$A separate couple shoot before the wedding for the save-the-date or the screens at the event. Plan time and a location. One of the shortlisted teams has a pre-wedding film section on their page.$q$, $q$💑$q$, $q$Extra shoot$q$, $q$pre wedding shoot ideas delhi couple$q$, $q$[{"label": "Decide", "value": "Do we want one?"}]$q$, 12),
($q$Album: flush-mount or coffee-table$q$, $q$Deliverable$q$, $q$A printed album of the best photos. Pick the size and number of pages in advance, because it affects the price.$q$, $q$📖$q$, $q$Deliverable$q$, $q$wedding album design flush mount india$q$, $q$[{"label": "Decide", "value": "Pages and size"}]$q$, 13),
($q$Digital gallery only$q$, $q$Deliverable$q$, $q$An online gallery you can share with family, with no printed album. Cheaper and quicker. Print favourites later.$q$, $q$☁️$q$, $q$Deliverable$q$, $q$wedding online photo gallery share family$q$, $q$[{"label": "Cost", "value": "Lower"}]$q$, 14),
($q$Photos of every function$q$, $q$Coverage$q$, $q$Cover Tilak, Mehndi, Sagai, Sangeet (14 Feb) and Haldi, Baraat, Varmala and the Mandap shaadi (15 Feb). The longest day is 15 Feb, running to midnight, so ask about the team size and breaks.$q$, $q$📅$q$, $q$Coverage$q$, $q$wedding photography coverage all functions india$q$, $q$[{"label": "Days", "value": "14 and 15 Feb 2027"}]$q$, 15),
($q$Two days: Sangeet and wedding only$q$, $q$Coverage$q$, $q$Cover only the Sangeet and the wedding day, and have a relative cover the smaller events. Lower cost, but you lose haldi and mehndi photos.$q$, $q$🎯$q$, $q$Coverage$q$, $q$wedding photography two functions only$q$, $q$[{"label": "Cost", "value": "Lower"}]$q$, 16),
($q$Must-have: getting-ready and details$q$, $q$Key shots$q$, $q$The outfits, jewellery, mehndi hands, shoes and invitation, and the mandap before guests arrive. Easy to forget and not possible to redo.$q$, $q$💍$q$, $q$Key shots$q$, $q$wedding detail shots jewellery mehndi hands invitation$q$, $q$[{"label": "When", "value": "Before each function"}]$q$, 17),
($q$Must-have: family portraits$q$, $q$Key shots$q$, $q$A list of family combinations (both families, siblings, grandparents) with one person to call each group. Takes 15 to 20 minutes and is the part elders care about.$q$, $q$👨‍👩‍👧‍👦$q$, $q$Key shots$q$, $q$wedding family portrait shot list india$q$, $q$[{"label": "Plan", "value": "A written shot list"}]$q$, 18),
($q$Must-have: couple portraits$q$, $q$Key shots$q$, $q$A short, unhurried slot for the two of you in good light, ideally before the baraat or during golden hour. Decide the time in advance.$q$, $q$❤️$q$, $q$Key shots$q$, $q$couple portraits wedding day golden hour india$q$, $q$[{"label": "Plan", "value": "A set time and place"}]$q$, 19),
($q$Must-have: the Sangeet performances$q$, $q$Key shots$q$, $q$Every group dance and the couple's dance, filmed from two angles. The cousins are working on routines already, so tell the team the order.$q$, $q$💃$q$, $q$Key shots$q$, $q$sangeet performance videography india$q$, $q$[{"label": "Plan", "value": "Share the performance order"}]$q$, 20),
($q$Photographer sample check$q$, $q$How to choose$q$, $q$Ask each team for a full gallery and a full video from one real wedding of a similar size, not only highlights. A friend in the field has offered to vet the work.$q$, $q$🔍$q$, $q$How to choose$q$, $q$how to choose wedding photographer india questions$q$, $q$[{"label": "Tip", "value": "See a whole wedding, not highlights"}]$q$, 21)
) as v(title, subtitle, detail, emoji, category, search, facts, sort_order)
